        A = int(assign['A'])
        U = int(assign['U'])
        sfreq = int(assign['sfreq'])
        t = int(assign['t'])
    except Exception:
        # invalid assignment
        return (False, None)
    # basic validations
    def is_prime(n):
        if n < 2:
            return False
        if n % 2 == 0:
            return n == 2
        d = 3
        while d * d <= n:
            if n % d == 0:
                return False
            d += 2
        return True
    if not (is_prime(m1) and is_prime(m2)):
        # need prime moduli for the intended CRT properties
        return (False, None)
    if not (1 <= r1 < m1 and 1 <= r2 < m2):
        return (False, None)
    if sfreq < 1 or A != 1 or U < 1:
        return (False, None)
    if t < 2:
        return (False, None)
    L = t**3 + 1
    if not (1 <= T < L):
        return (False, None)
    if gcd(L, m2) != 1:
        # ensure CRT for q works
        return (False, None)
    # build q as the minimal solution of q ≡ r2 (mod m2), q ≡ 0 (mod L)
    invL_mod_m2 = pow(L, -1, m2)
    t0 = (r2 * invL_mod_m2) % m2
    if t0 == 0:
        t0 = m2
    q = L * t0
    # minimality check: no smaller positive multiple of L satisfies the m2 congruence
    for s in range(1, t0):
        if (L * s) % m2 == r2:
            # not minimal
            return (False, None)
    # choose m1 to be coprime with L and q−1
    if gcd(L, m1) != 1 or gcd(q - 1, m1) != 1:
        return (False, None)
    # Solve for k such that k ≡ T (mod L) and k ≡ (r1 − T) * inv(q−1 mod m1) (mod m1)
    a = T % L
    inv_qm1_mod_m1 = pow((q - 1) % m1, -1, m1)
    b = ((r1 - T) % m1) * inv_qm1_mod_m1 % m1
    # CRT (L and m1 are coprime)
    k = a + L * ( ((b - a) * pow(L % m1, -1, m1)) % m1 )
    if k <= 0:
        k += L * m1
    p = T + k * (q - 1)
    # Check constraints
    if p % m1 != r1:
        return (False, None)
    if p % L != 0:
        return (False, None)
    # Check p ≡ T (mod (q−1))
    if (p - T) % (q - 1) != 0:
        return (False, None)
    # minimality check for p: ensure no smaller positive K satisfies both congruences
    for kk in range(1, k):
        candidate = T + kk * (q - 1)
        if candidate % L == 0 and candidate % m1 == r1:
            return (False, None)
    # Now compute the minimal value
    # Sequence pattern: per period L = t^3 + 1, indices 1..t^3 have sin(...) = +1 and index L has sin(...) = −1.
    # Then b_+ = (V − U)/A with V = ((t+1)/(t−1))U gives b_+ = 2U/(t−1); b_- = −t b_+; c = −b.
    b_plus = Fraction(2 * U, (t - 1))
    b_minus = -t * b_plus
    # Evaluate specific indices using periodicity: p ≡ 0 mod L ⇒ index L; q ≡ 0 mod L ⇒ index L; q−1 ≡ L−1 ⇒ index t^3
    a_p = Fraction(-1, 2 * sfreq)
    a_qm1 = Fraction(1, 2 * sfreq)
    b_p = b_minus
    b_q = b_minus
    c_q = -b_q
    c_pq = t * b_plus  # at index L of the period
    value = Fraction(p + q, 1) + 2 * a_p * a_p + b_q * b_q + c_pq * c_pq + (a_p + a_qm1) * (a_p + a_qm1) + (b_p + c_q) * (b_p + c_q)
    # format the answer
    def frac_to_latex(fr):
        fr = Fraction(fr.numerator, fr.denominator)
        if fr.denominator == 1:
            return str(fr.numerator)
        return f"\\frac{{{fr.numerator}}}{{{fr.denominator}}}"
    ans_str = f"### The final answer is: $\\boxed{{{frac_to_latex(value)}}}$"
    return (True, ans_str)


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
                valid, answer = verifier(assignment)
                if valid:
                    question = LANGUAGE_WRAPPER.format(**assignment)
                    return {
                        "assignment": assignment,
                        "question": question,
                        "answer": answer,
                        "attempts": attempts,
                        "elapsed_seconds": time.time() - start,
                    }
